import 'package:flutter_test/flutter_test.dart';import 'package:surge_wizard/core/combat_engine_v4.dart';import 'package:surge_wizard/core/combat_state_v4.dart';import 'package:surge_wizard/core/hex_coord_v4.dart';import 'package:surge_wizard/core/vertical_slice_catalog_v4.dart';void main(){test('Kael Guard applies Guarded and schedules action',(){final k=VerticalSliceCatalogV4.kael(),g=VerticalSliceCatalogV4.enemy('enemy_goblin_scout','g',const HexCoord(5,2));final e=CombatEngineV4(seed:4,units:[k,g]);k.nextActionTime=0;g.nextActionTime=20;e.beginNextActivation();e.kaelGuardStance();expect(k.has(StatusTypeV4.guarded),isTrue);});test('Nera Smoke Step relocates without opportunity and guards',(){final n=VerticalSliceCatalogV4.nera(),g=VerticalSliceCatalogV4.enemy('enemy_goblin_scout','g',const HexCoord(2,4));final e=CombatEngineV4(seed:5,units:[n,g]);n.nextActionTime=0;g.nextActionTime=20;e.beginNextActivation();expect(e.neraSmokeStep(const HexCoord(0,4)),isTrue);expect(n.has(StatusTypeV4.guarded),isTrue);});}
